def shortest_path(graph, source, target):
    from collections import deque
    import math

    # Initialize distances and previous nodes for dynamic programming
    distances = {node: math.inf for node in graph}
    previous = {node: None for node in graph}
    distances[source] = 0

    # Priority queue for BFS, using a min-heap
    queue = deque([(0, source)])  # (distance, node)

    while queue:
        current_distance, current_node = queue.popleft()

        # If we reach the target, reconstruct the path
        if current_node == target:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = previous[current_node]
            path.reverse()
            return (distances[target], path)

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous[neighbor] = current_node
                queue.append((distance, neighbor))

    # If we exit the loop without returning, the target node was unreachable
    return (math.inf, None)

