def shortest_path(graph, source, target):
    def bellman_ford(graph, source):
        # Initialize distance and predecessor
        distances = {node: float('inf') for node in graph}
        distances[source] = 0
        predecessors = {node: None for node in graph}

        # Relax edges |V| - 1 times
        for _ in range(len(graph) - 1):
            for node in graph:
                for neighbour, weight in graph[node]:
                    if distances[node] + weight < distances[neighbour]:
                        distances[neighbour] = distances[node] + weight
                        predecessors[neighbour] = node

        # Check for negative-weight cycles
        for node in graph:
            for neighbour, weight in graph[node]:
                if distances[node] + weight < distances[neighbour]:
                    raise ValueError("Graph contains a negative-weight cycle")

        return distances, predecessors

    distances, predecessors = bellman_ford(graph, source)

    # If the target node has a positive distance, the path exists
    if distances[target] == float('inf'):
        return float('inf'), None

    # Reconstruct the path
    path = []
    current_node = target
    while current_node is not None:
        path.append(current_node)
        current_node = predecessors[current_node]

    # If we want to include the starting node in the path, reverse it
    path.append(source)
    path.reverse()

    return distances[target], path

